import sqlparse


def test_repro_1():
    """Test that BEGIN TRANSACTION; ... END TRANSACTION; splits into four statements."""
    script = """BEGIN TRANSACTION;
DELETE FROM table1;
INSERT INTO table2 VALUES (1);
END TRANSACTION;"""
    statements = list(sqlparse.split(script))
    # We expect four separate statements: BEGIN TRANSACTION;, DELETE..., INSERT..., END TRANSACTION;
    assert len(statements) == 4, f"Expected 4 statements, got {len(statements)}: {[str(s) for s in statements]}"
    # Check the first statement is BEGIN TRANSACTION;
    assert str(statements[0]).strip().upper() == "BEGIN TRANSACTION;", f"First statement: {statements[0]}"
    # Check the last statement is END TRANSACTION;
    assert str(statements[-1]).strip().upper() == "END TRANSACTION;", f"Last statement: {statements[-1]}"


def test_repro_3():
    """Test using sqlparse.parsestream (alternative entry point) with a StringIO stream."""
    from io import StringIO
    script = """BEGIN TRANSACTION;
DELETE FROM table1;
INSERT INTO table2 VALUES (1);
END TRANSACTION;"""
    stream = StringIO(script)
    statements = list(sqlparse.parsestream(stream))
    assert len(statements) == 4, f"Expected 4 statements from parsestream, got {len(statements)}: {[str(s) for s in statements]}"
    # Ensure the statements are split correctly
    assert str(statements[0]).strip().upper() == "BEGIN TRANSACTION;"
    assert str(statements[3]).strip().upper() == "END TRANSACTION;"

